from ta_emss.utilities.trs.err_trs import ErrTrs


class ErrTransport(ErrTrs):
    '''Base class for exceptions related to TRS'''
    pass


class ErrTransportTimeout(ErrTransport):
    '''ErrTransport'''

    def __init__(self, err_data=None):
        super(ErrTransportTimeout, self).__init__(err_data)


class ErrTransportRecvQueueNotRegistered(ErrTransport):
    '''ErrTransportRecvQueueNotRegistered'''

    def __init__(self, err_data):
        super(ErrTransportRecvQueueNotRegistered, self).__init__(err_data)


class ErrRemoteEndpointDisconnected(ErrTransport):
    def __init__(self, err_data):
        super(ErrRemoteEndpointDisconnected, self).__init__(str(err_data))
        self.err = err_data


class ErrRemoteEndpointDead(ErrTransport):
    def __init__(self, err_data):
        super(ErrRemoteEndpointDead, self).__init__(str(err_data))
        self.err = err_data


class ErrPlayerUnexpectedDataSent(ErrTransport):
    def __init__(self, connection_name, expected, sent):
        msg = "replaying connection %s\nexpected: %s\nsent    : %s" % (connection_name, expected, sent)
        super(ErrPlayerUnexpectedDataSent, self).__init__(msg)
        self.expected = expected
        self.sent = sent


class ErrPlayerUnexpectedSent(ErrTransport):
    def __init__(self, connection_name, expected, sent):
        msg = "replaying connection %s\nexpected receive() of: %s\nperformed  send()  of: %s" % (connection_name, expected, sent)
        super(ErrPlayerUnexpectedSent, self).__init__(msg)
        self.connection_name = connection_name
        self.expected = expected
        self.sent = sent


class ErrPlayerUnexpectedReceive(ErrTransport):
    def __init__(self, connection_name, payload):
        msg = "replaying connection %s\nperformed receive() but expected send() of: %s" % (connection_name, payload)
        super(ErrPlayerUnexpectedReceive, self).__init__(msg)
        self.payload = payload
